int count = 42;
double ratio = 123.4567;
const char* name = "C Lang";

// Basic string output
printf("Starting Program...\n");

// Integer (%d, %u, %x)
printf("Count: %d (Unsigned: %u, Hex: %x)\n", count, count, count);

// Float (%f), precision control (%.2f)
printf("Ratio (2 DP): %.2f\n", ratio);

// String (%s) and Character (%c)
printf("Name: %s, First Letter: %c\n", name, name[0]);

// Field Width (Right alignment, 10 chars wide)
printf("|%10d|\n", count);

// Left alignment (- flag)
printf("|%-10s|", name);
